assignments.value:
={{ (() => {
  const b = $json.body;
  const errors = {};
  if (!b || typeof b !== 'object' || Array.isArray(b)) {
    return { valid: false, errors: { body: 'Expected a JSON object' }, record: null };
  }
  const str = v => (v === undefined || v === null) ? '' : String(v).trim();
  const event = str(b.event);
  const reference = str(b.reference);
  const email = str(b.customer_email).toLowerCase();
  const amount = typeof b.amount === 'string' && b.amount.trim() !== '' ? Number(b.amount) : b.amount;

  if (!event) errors.event = 'Required string, e.g. "order.created"';
  if (!reference) errors.reference = 'Required string (your unique reference)';
  if (!email) errors.customer_email = 'Required';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errors.customer_email = 'Not a valid email address';
  if (amount === undefined || amount === null || amount === '') errors.amount = 'Required number';
  else if (typeof amount !== 'number' || !Number.isFinite(amount)) errors.amount = 'Must be a number';
  else if (amount < 0) errors.amount = 'Must be >= 0';

  return {
    valid: Object.keys(errors).length === 0,
    errors,
    record: {
      event, reference, customer_email: email,
      amount: typeof amount === 'number' ? amount : null,
      currency: (str(b.currency) || 'IDR').toUpperCase().slice(0, 3),
      notes: str(b.notes).slice(0, 1000)
    }
  };
})() }}

parameters.jsonOutput:
={{ (() => {
  let p = {};
  try { p = JSON.parse($json.payload_json || '{}') ?? {}; } catch (e) { p = {}; }
  const amount = typeof p.amount === 'string' && p.amount.trim() !== '' ? Number(p.amount) : p.amount;
  return {
    'Request ID': $json.request_id,
    'Received At': $json.received_at,
    'Event': String(p.event ?? '').trim(),
    'Reference': String(p.reference ?? '').trim(),
    'Customer Email': String(p.customer_email ?? '').trim().toLowerCase(),
    'Amount': typeof amount === 'number' && Number.isFinite(amount) ? amount : null,
    'Currency': (String(p.currency ?? '').trim() || 'IDR').toUpperCase().slice(0, 3),
    'Notes': String(p.notes ?? '').trim().slice(0, 1000),
    'Stored Via': 'REPLAY'
  };
})() }}

parameters.responseBody:
={{ (() => {
  const id = String($('Status Webhook').first().json.query?.request_id ?? '').trim();
  if (!id) return { error: 'validation_error', message: 'Add ?request_id=<id> to the URL.' };
  if (!$json.request_id) return { error: 'not_found', message: 'No request with this ID has been logged.', request_id: id };
  const meaning = {
    STORED: 'Written to the sheet.',
    QUEUED: 'Accepted and waiting in the dead-letter queue. It will be written automatically; do not resend.',
    REJECTED: 'Rejected by validation. Fix the payload and resend.'
  };
  return { request_id: $json.request_id, status: $json.status, meaning: meaning[$json.status] ?? '', http_status: Number($json.http_status) || null, detail: $json.detail || null, received_at: $json.received_at, logged_at: $json.createdAt };
})() }}

assignments.value:
={{ (() => {
  const cfg = $('Report Settings').first().json;
  const logs = $('Get Last 24h Log').all().map(i => i.json).filter(r => r.status);
  const pending = $('Get Queue Backlog').all().map(i => i.json).filter(r => r.request_id);
  const count = (status, extra = () => true) => logs.filter(r => r.status === status && extra(r)).length;
  const reasons = {};
  logs.filter(r => r.status === 'REJECTED').forEach(r => {
    let fields;
    try { fields = Object.keys(JSON.parse(r.detail || '{}')); } catch (e) { fields = ['unreadable detail']; }
    (fields.length ? fields : ['unknown']).forEach(f => { reasons[f] = (reasons[f] || 0) + 1; });
  });
  const ages = pending.map(r => DateTime.fromISO(String(r.received_at ?? ''))).filter(t => t.isValid).map(t => Math.round($now.diff(t, 'minutes').minutes));
  const stuckAfter = Number(cfg.stuck_after_minutes) || 120;
  return {
    window: $now.minus({ hours: 24 }).toFormat('yyyy-MM-dd HH:mm') + ' → ' + $now.toFormat('yyyy-MM-dd HH:mm ZZZZ'),
    stored_direct: count('STORED', r => r.http_status === '200'),
    stored_replay: count('STORED', r => r.http_status !== '200'),
    queued: count('QUEUED'),
    rejected: count('REJECTED'),
    incidents: count('INCIDENT'),
    top_rejections: Object.entries(reasons).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([f, n]) => f + ' (' + n + ')'),
    backlog: pending.length,
    oldest_minutes: ages.length ? Math.max(...ages) : 0,
    stuck: ages.filter(a => a >= stuckAfter).length,
    stuck_after_minutes: stuckAfter
  };
})() }}

parameters.subject:
={{ (() => {
  const s = $json.stats;
  return 'Ingest report: ' + (s.stored_direct + s.stored_replay) + ' stored, ' + s.rejected + ' rejected, ' + s.backlog + ' in queue' + (s.stuck ? ' (' + s.stuck + ' stuck)' : '');
})() }}

parameters.message:
={{ (() => {
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const s = $json.stats;
  const doc = $('Replay · Upsert Rows in Sheet').params.documentId ?? {};
  const sheetUrl = doc.cachedResultUrl || (String(doc.value ?? '').startsWith('http') ? String(doc.value) : 'https://docs.google.com/spreadsheets/d/' + doc.value);
  const healthy = !s.backlog && !s.incidents;
  const row = (label, value, note) => '<tr><td style="padding:4px 12px 4px 0">' + label + '</td><td style="padding:4px 0"><b>' + value + '</b>' + (note ? ' <span style="color:#666">' + note + '</span>' : '') + '</td></tr>';
  return '<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:640px">' +
    '<h2 style="margin:0 0 4px 0">Daily ingest report</h2>' +
    '<p style="margin:0 0 12px 0;color:#666">' + esc(s.window) + '</p>' +
    '<p style="margin:0 0 12px 0;font-size:15px;color:' + (healthy ? '#0b6e4f' : '#b26a00') + '"><b>' + (healthy ? 'All clear: every request was stored.' : 'Needs attention: see the queue and incidents below.') + '</b></p>' +
    '<table cellpadding="0" cellspacing="0" style="border-collapse:collapse">' +
    row('Stored directly', s.stored_direct) +
    row('Stored after queueing', s.stored_replay) +
    row('Sent to the queue', s.queued) +
    row('Rejected (400)', s.rejected, s.top_rejections.length ? 'top fields: ' + s.top_rejections.map(esc).join(', ') : '') +
    row('Still in the queue', s.backlog, s.backlog ? 'oldest ' + s.oldest_minutes + ' min' : '') +
    row('Stuck over ' + s.stuck_after_minutes + ' min', s.stuck, s.stuck ? 'check the Google Sheets credential, quota and tab name' : '') +
    row('Incidents logged', s.incidents, s.incidents ? 'email alerts failed; see ingest_request_log' : '') +
    '</table>' +
    '<p style="margin-top:16px"><a href="' + esc(sheetUrl) + '">Open the Events sheet</a></p></div>';
})() }}

